package dev.zomboidmelee.boxing;
import dev.zomboidmelee.boxing.Checks16.*;import dev.zomboidmelee.boxing.CombatChecks18.*;import net.minecraft.client.Minecraft;import net.minecraft.client.model.*;import net.minecraft.client.model.geom.ModelPart;
public class GuardChecks23{
 static int checks;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 static double[]fist(Arms23.Joint j){double y=4+5*Math.cos(j.elbow()),z=5*Math.sin(j.elbow()),c=Math.cos(j.upper()),s=Math.sin(j.upper());return new double[]{2+y*c-z*s,y*s+z*c};}
 public static class Child extends ModelPart{int count;public void render(com.mojang.blaze3d.vertex.PoseStack p,Object c,int l,int o,int color){count++;}}
 public static void main(String[]args){Actor p=new Actor();Minecraft mc=Minecraft.INSTANCE;mc.player=p;mc.level=p.w;BoxingClient16.CLOCK=()->5_000_000_000L;var model=new ShadowModel();BoxingClient16.body(model,p);HumanoidModel<?>nativeModel=model;ok(nativeModel.rightArm.xRot<-1.2&&model.rightArm.rotX==0,"typed arm access, never GeoBone shadow");ok(Arms23.BINDINGS.containsKey(nativeModel.rightArm)&&Arms23.BINDINGS.containsKey(nativeModel.leftArm),"both third-person elbows bound");
 for(int side=0;side<2;side++){var guard=Arms23.joint(Motion20.LIGHT,side,0,1);double[]point=fist(guard);ok(guard.elbow()<-1.4&&point[0]<-1.5,"guard fist at lower face, not straight chest-height arm");ok(point[1]<-3&&point[1]>-7,"fist close in front of face");}
 var g=Arms23.joint(0,0,0,1);var j=Arms23.joint(0,0,0,.25);ok(j.elbow()>g.elbow()+1.5,"jab extends actual elbow");ok(fist(j)[1]<fist(g)[1]-2,"jab travels toward target");
 Pose pose=new Pose();Child child=new Child();nativeModel.rightArm.children.put("decoration",child);int renders=ModelPart.renders;ok(Arms23.render(nativeModel.rightArm,pose,new Object(),1,0,-1),"native arm render replaced only while bound");ok(ModelPart.renders-renders==2&&child.count==1&&pose.depth==0,"two segments, attachment retained, balanced matrix");nativeModel.rightArm.visible=false;renders=ModelPart.renders;Arms23.render(nativeModel.rightArm,pose,new Object(),1,0,-1);ok(ModelPart.renders==renders,"invisible arm stays invisible");nativeModel.rightArm.visible=true;nativeModel.rightArm.skipDraw=true;Arms23.render(nativeModel.rightArm,pose,new Object(),1,0,-1);ok(ModelPart.renders==renders&&child.count==2,"skipDraw preserves attached parts without skin");nativeModel.rightArm.skipDraw=false;
 p.off=new Stack(false);BoxingClient16.body(model,p);ok(!Arms23.BINDINGS.containsKey(nativeModel.leftArm)&&Arms23.BINDINGS.containsKey(nativeModel.rightArm),"offhand arm left to native item render");p.main=new Stack(false);BoxingClient16.body(model,p);ok(Arms23.BINDINGS.isEmpty(),"weapon handoff removes all limb overrides");p.main=new Stack(true);p.off=new Stack(true);
 Hand hand=new Hand();renders=ModelPart.renders;BoxingClient16.hand(hand);ok(hand.canceled&&ModelPart.renders-renders==8&&hand.pose.depth==0,"first-person skin upper/forearm and sleeve chains render for both hands");
 Actor fighter=new Actor();fighter.baseAttack=1;ok(HeavyDamage23.amount(fighter)==2,"heavy double normal base 1");fighter.baseAttack=3.75;ok(HeavyDamage23.amount(fighter)==7.5,"heavy scales with player attack attribute");Zombie target=new Zombie(fighter.w);fighter.w.entities.put(1,target);Combat18.heavy(fighter,1);ok(target.damage==7.5,"actual heavy hurt uses doubled base, not fixed three");ok(Combat18.NEXT.get(fighter)==fighter.w.time+18,"heavy cooldown unchanged");
 for(int kind=0;kind<=5;kind++)for(int i=0;i<=100;i++){var q=Arms23.joint(kind,0,0,i/100d);ok(Double.isFinite(q.upper()+q.elbow()+q.yaw()+q.roll()),"finite joint track");}for(int i=12;i<=84;i++){var q=StompMotion21.pose(i/100d,.7,.2,.08,1.6);ok(Math.abs(q.ankle())<=10.01,"stomp foot stays flat, not sole toward face");}
 System.out.println("ARTICULATED_FIRST_THIRD_PERSON_GUARD_OFFHAND_ATTACHMENTS_DOUBLE_HEAVY_CHECKS="+checks);
 }
}
